const test = require('node:test');
const assert = require('node:assert/strict');
const { utcMillis } = require('../src/utc-components.cjs');

test("one argument denotes a year with default month and day", () => {
  assert.equal(utcMillis(2026), 1767225600000);
  assert.equal(utcMillis(2026, 6), 1782864000000);
  assert.equal(utcMillis(2026, 6, 18, 9, 2, 3, 4), 1784365323004);
});

test("small year numbers use the documented 1900 mapping", () => {
  assert.equal(new Date(utcMillis(0)).toISOString(), '1900-01-01T00:00:00.000Z');
  assert.equal(new Date(utcMillis(26, 0, 2)).toISOString(), '1926-01-02T00:00:00.000Z');
  assert.equal(new Date(utcMillis(99, 11, 31)).toISOString(), '1999-12-31T00:00:00.000Z');
  assert.equal(new Date(utcMillis(100, 0, 1)).toISOString(), '0100-01-01T00:00:00.000Z');
});

test("invalid numeric components yield NaN", () => {
  assert.equal(Number.isNaN(utcMillis(NaN)), true);
  assert.equal(Number.isNaN(utcMillis(2026, undefined)), true);
});

test("out of range components normalize instead of being rejected", () => {
  assert.equal(new Date(utcMillis(2026, 15, 0)).toISOString(), '2027-03-31T00:00:00.000Z');
  assert.equal(new Date(utcMillis(2026, 0, 1, -1)).toISOString(), '2025-12-31T23:00:00.000Z');
});

